local nextId = 0
local function nodesFor(value, ancestors)
    local nodes = {}
    for key, item in pairs(value) do
        nextId += 1
        local isTable = type(item) == "table"
        local cyclic = isTable and ancestors[item] == true
        local node = {
            id = nextId, -- Unique across all lazy-loaded branches.
            text = tostring(key) .. " = " .. (if cyclic then "[cycle]" else tostring(item)),
            data = { key = key, value = item }, -- Preserve raw keys and values.
        }
        if isTable and not cyclic then
            local path = table.clone(ancestors)
            path[item] = true
            node.loadChildren = function() return nodesFor(item, path) end
        end
        table.insert(nodes, node)
    end
    table.sort(nodes, function(a, b) return a.text < b.text end)
    return nodes
end

